      svg: `<svg viewBox="0 0 560 275" xmlns="http://www.w3.org/2000/svg" font-size="13" fill="currentColor">
<defs><marker id="ar-c12-geo-14" viewBox="0 0 10 10" refX="9" refY="5" markerUnits="userSpaceOnUse" markerWidth="9" markerHeight="9" orient="auto"><path d="M0 0L10 5L0 10z" fill="var(--dg-accent)"/></marker></defs><line x1="10" y1="18" x2="550" y2="18" stroke="var(--dg-accent)" stroke-width="2" marker-end="url(#ar-c12-geo-14)"/><text x="10" y="12" fill="var(--dg-muted)" font-size="12">Time</text><rect x="8" y="32" width="130" height="190" rx="4" fill="var(--dg-fill)" fill-opacity="0.2" stroke="currentColor" stroke-width="1.5"/><text x="73" y="52" text-anchor="middle" fill="var(--dg-muted)" font-size="12">Phase I</text><text x="73" y="72" text-anchor="middle" font-weight="bold">1901–1921</text><text x="73" y="96" text-anchor="middle" font-weight="bold" fill="var(--dg-accent)" font-size="12">Stagnant phase</text><text x="73" y="124" text-anchor="middle" font-size="12">Birth and death</text><text x="73" y="141" text-anchor="middle" font-size="12">rates both high;</text><text x="73" y="158" text-anchor="middle" font-size="12">poor health services,</text><text x="73" y="175" text-anchor="middle" font-size="12">illiteracy</text><rect x="146" y="32" width="130" height="190" rx="4" fill="var(--dg-fill)" fill-opacity="0.30000000000000004" stroke="currentColor" stroke-width="1.5"/><text x="211" y="52" text-anchor="middle" fill="var(--dg-muted)" font-size="12">Phase II</text><text x="211" y="72" text-anchor="middle" font-weight="bold">1921–1951</text><text x="211" y="96" text-anchor="middle" font-weight="bold" fill="var(--dg-accent)" font-size="12">Steady growth</text><text x="211" y="124" text-anchor="middle" font-size="12">Health, sanitation and</text><text x="211" y="141" text-anchor="middle" font-size="12">transport improve;</text><text x="211" y="158" text-anchor="middle" font-size="12">mortality falls</text><rect x="284" y="32" width="130" height="190" rx="4" fill="var(--dg-fill)" fill-opacity="0.4" stroke="currentColor" stroke-width="1.5"/><text x="349" y="52" text-anchor="middle" fill="var(--dg-muted)" font-size="12">Phase III</text><text x="349" y="72" text-anchor="middle" font-weight="bold">1951–1981</text><text x="349" y="96" text-anchor="middle" font-weight="bold" fill="var(--dg-accent)" font-size="12">Population explosion</text><text x="349" y="124" text-anchor="middle" font-size="12">Mortality falls fast,</text><text x="349" y="141" text-anchor="middle" font-size="12">fertility stays high;</text><text x="349" y="158" text-anchor="middle" font-size="12">growth rate 2.2%</text><text x="349" y="175" text-anchor="middle" font-size="12">a year</text><rect x="422" y="32" width="130" height="190" rx="4" fill="var(--dg-fill)" fill-opacity="0.5" stroke="currentColor" stroke-width="1.5"/><text x="487" y="52" text-anchor="middle" fill="var(--dg-muted)" font-size="12">Phase IV</text><text x="487" y="72" text-anchor="middle" font-weight="bold">after 1981</text><text x="487" y="96" text-anchor="middle" font-weight="bold" fill="var(--dg-accent)" font-size="12">High but slowing</text><text x="487" y="124" text-anchor="middle" font-size="12">Falling birth rate,</text><text x="487" y="141" text-anchor="middle" font-size="12">later marriage,</text><text x="487" y="158" text-anchor="middle" font-size="12">more female</text><text x="487" y="175" text-anchor="middle" font-size="12">education</text><text x="280" y="246" text-anchor="middle" fill="var(--dg-muted)" font-size="12">1921 is the 'year of the great demographic divide'</text><text x="280" y="264" text-anchor="middle" fill="var(--dg-muted)" font-size="12">1961–71 recorded the highest decadal growth rate</text>
</svg>`,
